public class Types {
    public static void main(String[] args) {
        final double VAT = 0.15;          // constant
        int apples = 7, people = 2;
        System.out.println(apples / people);        // 3  (integer division)
        System.out.println((double) apples / people); // 3.5
        System.out.println(apples % people);        // 1
        int chopped = (int) 3.99;                   // 3
        char grade = 'A';
        System.out.println(grade + 1);              // 66 (char becomes number)
        System.out.println((char)(grade + 1));      // B
        String s = null;                            // allowed: reference type
        // s.length();  -> NullPointerException
    }
}

